const email = $input.first().json.body.Email || "";
const namePart = email.split('@')[0];

// Verifica se tem muitos números
const hasManyNumbers = (namePart.match(/\d/g) || []).length > 5;

// Verifica se é muito curto ou muito longo
const isTooShortOrLong = namePart.length < 5 || namePart.length > 20;

// Verifica se é só letras e números
const isAlphanumericOnly = /^[a-z0-9]+$/i.test(namePart);

// Se todas essas condições forem verdadeiras, parece aleatório
const isProbablyRandom = hasManyNumbers && isAlphanumericOnly && isTooShortOrLong;

return [{ json: { isRandomEmail: isProbablyRandom } }];

const users = $input.first().json.data; // retorno do HTTP Request
const nomeFormulario = $('Webhook').first().json.body['Closer'] || '';

const norm = s => (s || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().trim();

const alvo = norm(nomeFormulario);
const user = users.find(u => norm(u.name) === alvo);

if (!user) {
  throw new Error(`Closer não encontrado por nome: ${nomeFormulario}`);
}

return [{ json: { owner_id: user.id, closer_name: user.name } }];

